{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Untie context and prediction embeddings across all four category models while retaining width, row normalization and radius. Copy initial real-item input rows into the output table, then train both jointly. This may reduce conflicting embedding gradients. The generated predictor imports the updated model class and strictly loads its checkpoint, preserving architecture consistency.",
      "edits": [
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)\n        self.output_item_weight = nn.Parameter(torch.empty(itemnum + 1, hidden_units))\n        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)"
        },
        {
          "find": "            self.item_emb.weight[0].zero_()\n            nn.init.xavier_uniform_(self.pos_emb.weight)",
          "replace": "            self.item_emb.weight[0].zero_()\n            self.output_item_weight.copy_(self.item_emb.weight[:itemnum + 1])\n            nn.init.xavier_uniform_(self.pos_emb.weight)"
        },
        {
          "find": "    def encode_sequence(self, seq: torch.Tensor) -> torch.Tensor:",
          "replace": "    def effective_output_weight(self) -> torch.Tensor:\n        row_norm = math.sqrt(2.0 * self.hidden_units / (self.itemnum + 2 + self.hidden_units))\n        nonpadding = torch.nn.functional.normalize(\n            self.output_item_weight[1:], p=2, dim=-1, eps=1e-12\n        ) * row_norm\n        return torch.cat((torch.zeros_like(self.output_item_weight[:1]), nonpadding), dim=0)\n\n    def encode_sequence(self, seq: torch.Tensor) -> torch.Tensor:"
        },
        {
          "find": "        masked_states, model.effective_item_weight()[1:model.itemnum + 1]",
          "replace": "        masked_states, model.effective_output_weight()[1:model.itemnum + 1]"
        },
        {
          "find": "        item_weight = self.effective_item_weight()\n        pos_scores",
          "replace": "        item_weight = self.effective_output_weight()\n        pos_scores"
        },
        {
          "find": "            candidates, self.effective_item_weight(), padding_idx=0",
          "replace": "            candidates, self.effective_output_weight(), padding_idx=0"
        }
      ]
    }
  ],
  "change_summary": "Untie normalized input and output item embeddings within each category’s single BERT4Rec model. Preserve initialization values, embedding radius, masked training, dot-product scoring and predictor/checkpoint consistency."
}
